using Microsoft.ML.Data;

namespace TicketClassifier.Models;

/// <summary>
/// Input schema matching the training CSV.
/// </summary>
public class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

/// <summary>
/// ML.NET prediction output.
/// </summary>
public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedCategory { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

/// <summary>
/// API request body for the prediction endpoint.
/// </summary>
public class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; } = 3;
}

/// <summary>
/// API response with prediction and confidence scores.
/// </summary>
public class TicketResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> Confidence { get; set; } = new();
}

/// <summary>
/// Evaluation metrics returned by the training endpoint.
/// </summary>
public class TrainingMetrics
{
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
    public List<CategoryMetric> PerClassMetrics { get; set; } = [];
}

public class CategoryMetric
{
    public string Category { get; set; } = string.Empty;
    public double Precision { get; set; }
    public double Recall { get; set; }
    public double F1Score { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelService
{
    private readonly MLContext _mlContext;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketModelService> _logger;

    public TicketModelService(ILogger<TicketModelService> logger, IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "ticket_model.zip");
        _logger = logger;
    }

    public string ModelPath => _modelPath;

    /// <summary>
    /// Trains the model, evaluates it, saves it to disk, and returns metrics.
    /// </summary>
    public TrainingMetrics TrainAndEvaluate()
    {
        _logger.LogInformation("Loading training data from {Path}", _dataPath);

        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // With a small dataset, train on all data and evaluate on all data.
        // In production with more data, use TrainTestSplit.
        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.3, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .AppendCacheCheckpoint(_mlContext)
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        _logger.LogInformation("Evaluating model...");
        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        _logger.LogInformation(
            "MacroAccuracy={Macro:F4}, MicroAccuracy={Micro:F4}, LogLoss={LogLoss:F4}",
            metrics.MacroAccuracy, metrics.MicroAccuracy, metrics.LogLoss);

        _mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        var result = new TrainingMetrics
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
        };

        // Extract per-class metrics from the confusion matrix
        var cm = metrics.ConfusionMatrix;
        for (int i = 0; i < cm.PerClassPrecision.Count; i++)
        {
            result.PerClassMetrics.Add(new CategoryMetric
            {
                Category = cm.GetFormattedConfusionTable()
                    .Contains("Billing") ? GetClassLabel(cm, i) : $"Class_{i}",
                Precision = cm.PerClassPrecision[i],
                Recall = cm.PerClassRecall[i],
                F1Score = 2 * cm.PerClassPrecision[i] * cm.PerClassRecall[i]
                    / (cm.PerClassPrecision[i] + cm.PerClassRecall[i] + 1e-10),
            });
        }

        return result;
    }

    private static string GetClassLabel(ConfusionMatrix cm, int index)
    {
        // Parse class names from the formatted confusion matrix table
        var table = cm.GetFormattedConfusionTable();
        var categories = new[] { "Billing", "General", "Technical" };
        var found = new List<string>();
        foreach (var cat in categories)
        {
            if (table.Contains(cat))
                found.Add(cat);
        }

        found.Sort();
        return index < found.Count ? found[index] : $"Class_{index}";
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly TicketModelService _modelService;
    private readonly ILogger<TicketController> _logger;

    private static readonly string[] Categories = ["Billing", "General", "Technical"];

    public TicketController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        TicketModelService modelService,
        ILogger<TicketController> logger)
    {
        _predictionPool = predictionPool;
        _modelService = modelService;
        _logger = logger;
    }

    /// <summary>
    /// Predicts the category of a support ticket.
    /// </summary>
    [HttpPost("classify")]
    public ActionResult<TicketResponse> Classify([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description is required.");

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        if (!System.IO.File.Exists(_modelService.ModelPath))
            return StatusCode(503, "Model not trained yet. POST to /api/ticket/train first.");

        var input = new TicketInput
        {
            Subject = request.Subject ?? string.Empty,
            Description = request.Description ?? string.Empty,
            Priority = request.Priority,
        };

        var prediction = _predictionPool.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < Categories.Length; i++)
        {
            confidence[Categories[i]] = prediction.Score[i];
        }

        _logger.LogInformation(
            "Classified ticket as {Category} (confidence: {Confidence:F2})",
            prediction.PredictedCategory,
            confidence.GetValueOrDefault(prediction.PredictedCategory));

        return Ok(new TicketResponse
        {
            PredictedCategory = prediction.PredictedCategory,
            Confidence = confidence,
        });
    }

    /// <summary>
    /// Trains (or re-trains) the model and returns evaluation metrics.
    /// </summary>
    [HttpPost("train")]
    public ActionResult<TrainingMetrics> Train()
    {
        var metrics = _modelService.TrainAndEvaluate();
        return Ok(metrics);
    }
}

