        for (int i = 0; i < prediction.Score.Length && i < Categories.Length; i++)
        {
            confidence[Categories[i]] = prediction.Score[i];
        }

        _logger.LogInformation(
            "Classified ticket as {Category} (confidence: {Confidence:F2})",
            prediction.PredictedCategory,
            confidence.GetValueOrDefault(prediction.PredictedCategory));

        return Ok(new TicketResponse
        {
            PredictedCategory = prediction.PredictedCategory,
            Confidence = confidence,
        });
    }

    /// <summary>
    /// Trains (or re-trains) the model and returns evaluation metrics.
    /// </summary>
    [HttpPost("train")]
    public ActionResult<TrainingMetrics> Train()
    {
        var metrics = _modelService.TrainAndEvaluate();
        return Ok(metrics);
    }
}
"}

